import { iterateSlots } from '../functions/iterate-slots.js';
import { createXYChartConfiguration } from '../functions/xy-chart-configuration.js';
import type { XYChartConfiguration } from '../types/xy-chart.js';

export const useXYChartConfig = (
  children?: React.ReactNode,
): XYChartConfiguration => {
  const slots = iterateSlots(children);

  return createXYChartConfiguration(slots);
};
